class BizException extends Error {
  constructor(code, message){ super(message); this.code = code; this.biz = true; }
}

const ERROR_CODES = {
  USER_NOT_FOUND: { code: 1001, http: 404, msg: "用户不存在" },
  INSUFFICIENT:   { code: 2001, http: 400, msg: "余额不足" },
  SYS:            { code: 5000, http: 500, msg: "系统错误" },
};
function buildResponse(key, detail) {
  const e = ERROR_CODES[key];
  return { httpStatus: e.http, body: { code: e.code, message: e.msg, detail: detail ?? null } };
}
console.log(JSON.stringify(buildResponse("USER_NOT_FOUND")));
console.log(JSON.stringify(buildResponse("INSUFFICIENT", "need 50")));
